import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './Profile.css';

const Profile = () => {
  const [userDetails, setUserDetails] = useState({});
  const [userProducts, setUserProducts] = useState([]);
  const [errorMessage, setErrorMessage] = useState('');
  const [profileImage, setProfileImage] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    // Fetch profile image from local storage
    const savedImage = localStorage.getItem('profileImage');
    if (savedImage) {
      setProfileImage(savedImage);
    } else {
      // Set a default image if no image is in local storage
      setProfileImage('/default-profile.jpg'); // Add a default image to your `public` folder
    }

    const fetchUserDetails = async () => {
      try {
        const token = localStorage.getItem('token');
        if (!token) {
          navigate('/login');
          return;
        }

        const response = await axios.get('http://localhost:8080/api/auth/login', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (response.data.user) {
          setUserDetails(response.data.user);
          fetchUserProducts(response.data.user.id);
        } else {
          setErrorMessage(response.data.message || 'Failed to fetch user details.');
        }
      } catch (error) {
        setErrorMessage(
          error.response?.data?.message || 'An error occurred. Please try again.'
        );
      }
    };

    const fetchUserProducts = async (userId) => {
      try {
        const response = await axios.get(`http://localhost:8080/api/products/user/${userId}`);
        setUserProducts(response.data);
      } catch (error) {
        setErrorMessage(
          error.response?.data?.message || 'Failed to fetch user products.'
        );
      }
    };

    fetchUserDetails();
  }, [navigate]);

  const handleAddProduct = () => {
    navigate('/add-product');
  };

  const handleImageChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        // Save the new image to local storage and state
        const imageBase64 = reader.result;
        localStorage.setItem('profileImage', imageBase64);
        setProfileImage(imageBase64);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="profile-container left-aligned">
      <h2>Profile</h2>
      {errorMessage && <p className="error-message">{errorMessage}</p>}
      {!errorMessage && (
        <div>
          {/* Profile Image */}
          <div className="profile-image-container">
            <img src={profileImage} alt="Profile" className="profile-image" />
            <input
              type="file"
              accept="image/*"
              onChange={handleImageChange}
              className="image-upload"
            />
          </div>

          <p><strong>ID:</strong> {userDetails.id || 'N/A'}</p>
          <p><strong>Name:</strong> {userDetails.name || 'N/A'}</p>
          <p><strong>Email:</strong> {userDetails.email || 'N/A'}</p>
          <p><strong>Role:</strong> {typeof userDetails.role === 'object' ? JSON.stringify(userDetails.role) : userDetails.role || 'N/A'}</p>
          <button className="add-product-button" onClick={handleAddProduct}>
            Add Product
          </button>

          <h3>Products</h3>
          {userProducts.length > 0 ? (
            <div>
              {userProducts.map((product) => (
                <div className="product-card" key={product.id}>
                  <h4>{product.name}</h4>
                  <p><strong>Price:</strong> ₹{product.price}</p>
                  <p><strong>Quantity:</strong> {product.quantity}</p>
                  <p><strong>Description:</strong> {product.description}</p>
                  <p><strong>Listed on:</strong> {product.listingDate}</p>
                </div>
              ))}
            </div>
          ) : (
            <p>No products found for this user.</p>
          )}
        </div>
      )}
    </div>
  );
};

export default Profile;
